mapper.select:
select pou.id, pou.order_number, pou.owner_unit, ou.C_Name as ownerUnitName, pou.project_manger, pmu.U_Name as projectMangerName, pou.project_leader, plu.U_Name as projectLeaderName, pou.remark, pou.p_id from pp_owner_unit pou left join sys_company ou on ou.C_ID = pou.owner_unit left join sys_user pmu on pmu.U_ID = pou.project_manger left join sys_user plu on plu.U_ID = pou.project_leader where pou.p_id in
#{item}
order by order_number asc
